// clang -fobjc-arc -framework Foundation -framework Metal mesh_probe.m -o mesh_probe
// Run with the directory generated by make_mesh_probe.py. No game data is used.
#import <Foundation/Foundation.h>
#import <Metal/Metal.h>

int main(int argc, const char **argv) {
    @autoreleasepool {
        if (argc != 2) return 2;
        id<MTLDevice> device = MTLCreateSystemDefaultDevice(); if (!device) return 1;
        NSError *error = nil;
        NSString *dir = @(argv[1]);
        NSString *taskSource = [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"task.metal"] encoding:NSUTF8StringEncoding error:&error];
        NSString *meshSource = [NSString stringWithContentsOfFile:[dir stringByAppendingPathComponent:@"mesh.metal"] encoding:NSUTF8StringEncoding error:&error];
        if (!taskSource || !meshSource) return 1;
        id<MTLLibrary> task = [device newLibraryWithSource:taskSource options:nil error:&error];
        id<MTLLibrary> mesh = [device newLibraryWithSource:meshSource options:nil error:&error];
        MTLMeshRenderPipelineDescriptor *descriptor = [MTLMeshRenderPipelineDescriptor new];
        descriptor.objectFunction = [task newFunctionWithName:@"main0"];
        descriptor.meshFunction = [mesh newFunctionWithName:@"main0"];
        descriptor.fragmentFunction = [mesh newFunctionWithName:@"pixel"];
        if (!descriptor.objectFunction || !descriptor.meshFunction || !descriptor.fragmentFunction) {
            fprintf(stderr, "%s\n", error.description.UTF8String); return 1;
        }
        descriptor.maxTotalThreadsPerObjectThreadgroup = 32;
        descriptor.maxTotalThreadsPerMeshThreadgroup = 32;
        descriptor.payloadMemoryLength = 48;
        descriptor.colorAttachments[0].pixelFormat = MTLPixelFormatRGBA8Unorm;
        id<MTLRenderPipelineState> pipeline = [device newRenderPipelineStateWithMeshDescriptor:descriptor options:MTLPipelineOptionNone reflection:nil error:&error];
        if (!pipeline) { fprintf(stderr, "%s\n", error.description.UTF8String); return 1; }
        MTLTextureDescriptor *td = [MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:16 height:16 mipmapped:NO];
        td.storageMode = MTLStorageModePrivate; td.usage = MTLTextureUsageRenderTarget;
        id<MTLTexture> texture = [device newTextureWithDescriptor:td];
        id<MTLBuffer> pixels = [device newBufferWithLength:4096 options:MTLResourceStorageModeShared];
        id<MTLCommandQueue> queue = [device newCommandQueue]; id<MTLCommandBuffer> command = [queue commandBuffer];
        MTLRenderPassDescriptor *pass = [MTLRenderPassDescriptor renderPassDescriptor];
        pass.colorAttachments[0].texture = texture; pass.colorAttachments[0].loadAction = MTLLoadActionClear;
        pass.colorAttachments[0].storeAction = MTLStoreActionStore; pass.colorAttachments[0].clearColor = MTLClearColorMake(0,0,0,0);
        id<MTLRenderCommandEncoder> encoder = [command renderCommandEncoderWithDescriptor:pass];
        [encoder setRenderPipelineState:pipeline]; [encoder setCullMode:MTLCullModeNone];
        uint32_t first = 7; [encoder setObjectBytes:&first length:4 atIndex:29]; [encoder setMeshBytes:&first length:4 atIndex:29];
        [encoder drawMeshThreadgroups:MTLSizeMake(1,1,1) threadsPerObjectThreadgroup:MTLSizeMake(32,1,1) threadsPerMeshThreadgroup:MTLSizeMake(32,1,1)];
        [encoder endEncoding];
        id<MTLBlitCommandEncoder> blit = [command blitCommandEncoder];
        [blit copyFromTexture:texture sourceSlice:0 sourceLevel:0 sourceOrigin:MTLOriginMake(0,0,0) sourceSize:MTLSizeMake(16,16,1) toBuffer:pixels destinationOffset:0 destinationBytesPerRow:256 destinationBytesPerImage:4096];
        [blit endEncoding]; [command commit]; [command waitUntilCompleted];
        if (command.status != MTLCommandBufferStatusCompleted) { fprintf(stderr, "%s\n", command.error.description.UTF8String); return 1; }
        const uint8_t *bytes = pixels.contents; const int expected[4] = {112,128,191,255};
        for (int y=0;y<16;y++) for (int x=0;x<16;x++) for (int c=0;c<4;c++) {
            if (abs(bytes[y*256+x*4+c]-expected[c]) > 1) {
                fprintf(stderr, "Mesh pixel %d,%d channel%d = %u, expected%d\n", x,y,c,bytes[y*256+x*4+c],expected[c]); return 1;
            }
        }
        puts("Task/mesh GPU readback passed: task number -> payload -> vertex output -> 256 rendered pixels");
    }
    return 0;
}
